head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > E > onchange]<br/>SearchBox 컴포넌트에서 입력값이 변경된 후 포커스 아웃 시 발생합니다.",
    "validation" : [
        "SearchBox 컴포넌트에서 입력값이 변경된 후 포커스 아웃 시 onchange 이벤트가 발생합니다.",
        "setValue() 메소드로 값을 변경한 경우에도 onchange 이벤트가 발생합니다.",
        "info 파라미터로 변경 전후의 값 정보를 담은 객체가 전달됩니다.",
        "info.oldValue 속성으로 변경 전 값이 전달됩니다.",
        "info.newValue 속성으로 변경 후 값이 전달됩니다.",
        "입력값 변경 후 포커스가 빠질 때 'onchange -> onviewchange -> onblur' 순서로 이벤트가 발생합니다.",        
        "이전값과 현재값이 동일하면 이벤트가 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {}

    let cList = $c.gcm.createCList(properties)
    let eList = $c.gcm.createEList(["onchange", "onviewchange", "onblur"])

    // comp 생성 함수 호출 (searchbox 는 비동기 plugin → await 필수)
    await $c.gcm.createBasicSearchBox(cList, eList);
}



// onchange 핸들러 (e 는 한 줄, info 속성은 개별 출력)
scwin.target1_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
};



// onviewchange 핸들러 (이벤트 순서 확인용)
scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange 이벤트 발생=====");
};



// onblur 핸들러 (이벤트 순서 확인용)
scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblur 이벤트 발생=====");
};



// setValue 로 입력값 변경 → onchange 발생 확인
scwin.btn_setValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("----- setValue('changedBySetValue') 호출 -----");
    target1.setValue("changedBySetValue");
};



// 현재값과 동일한 값으로 setValue → onchange 발생하지 않음 확인
scwin.btn_setSameValue_onclick = function (e) {
    let curVal = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("----- 현재값(" + curVal + ")과 동일한 값으로 setValue 호출 (onchange 미발생 예상) -----");
    target1.setValue(curVal);
};
